                 "戦闘 SKILL/ITEM/GUARD/RUN", "GUARD:今ターンの被害半減", "技は使い切ると消滅"]
        for i, line in enumerate(lines):
            text(5, 18 + i * 10, line, 3 if i < 5 else 2, 37)
